import assert from "node:assert/strict";
import test from "node:test";
import { JSDOM } from "/Users/vadikone/.bb/thread-storage/thr_bza87x5nhg/minus-source/node_modules/jsdom/lib/api.js";
import { mountToolGrouping } from "/Users/vadikone/.bb/thread-storage/thr_bza87x5nhg/minus-source/group-tools.ts";
import { QUOTE_SOURCES, QUOTES, pickRandomQuote } from "/Users/vadikone/.bb/thread-storage/thr_bza87x5nhg/minus-source/quotes.ts";

const HIDDEN = "data-bb-minus-hidden";

function fullId(id) {
  return id.startsWith("thr_") ? id : "thr_test:" + (id.startsWith("tool-") ? "tool:" : "") + id;
}

function makeRow(window, id) {
  const row = window.document.createElement("div");
  row.setAttribute("data-timeline-row-id", fullId(id));
  return row;
}

function mountDom({ rowIds, fetchTimeline, chooseQuote = () => QUOTES[0], clock, subscribeTimeline }) {
  const dom = new JSDOM("<!doctype html><html><head></head><body></body></html>", {
    pretendToBeVisual: true,
    url: "https://bb.local/",
  });
  const { window } = dom;
  const globals = {
    document: window.document,
    Element: window.Element,
    HTMLElement: window.HTMLElement,
    MutationObserver: window.MutationObserver,
    requestAnimationFrame: window.requestAnimationFrame.bind(window),
    cancelAnimationFrame: window.cancelAnimationFrame.bind(window),
  };
  const previousGlobals = new Map();
  for (const [name, value] of Object.entries(globals)) {
    previousGlobals.set(name, Object.getOwnPropertyDescriptor(globalThis, name));
    Object.defineProperty(globalThis, name, { configurable: true, writable: true, value });
  }

  const list = window.document.createElement("div");
  list.setAttribute("data-timeline-row-list", "top-level");
  const container = window.document.createElement("div");
  container.setAttribute("data-timeline-items", "");
  const rows = rowIds.map((id) => makeRow(window, id));
  container.append(...rows);
  list.append(container);
  window.document.body.append(list);
  const dispose = mountToolGrouping(fetchTimeline, chooseQuote, clock, subscribeTimeline);

  return {
    window,
    container,
    rows,
    dispose,
    makeRow: (id) => makeRow(window, id),
    async flush() {
      for (let index = 0; index < 2; index++) {
        await Promise.resolve();
        await new Promise((resolve) => window.setTimeout(resolve, 0));
        await new Promise((resolve) => window.requestAnimationFrame(resolve));
      }
    },
    cleanup() {
      dispose();
      for (const [name, descriptor] of previousGlobals) {
        if (descriptor) Object.defineProperty(globalThis, name, descriptor);
        else delete globalThis[name];
      }
      window.close();
    },
  };
}

function timeline(rows) {
  return rows.map(([id, kind = "work", operationKind, startedAt = 1000, completedAt = 1300, workKind]) => ({
    id: fullId(id),
    kind,
    startedAt,
    ...(kind === "work" ? {
      completedAt,
      status: completedAt === null ? "pending" : "completed",
    } : {}),
    ...(operationKind === undefined ? {} : { operationKind }),
    ...(workKind === undefined ? {} : { workKind }),
  }));
}

function makeClock(startAt) {
  let now = startAt;
  let nextId = 0;
  const timers = new Map();
  return {
    now: () => now,
    setTimeout(callback, delayMs) {
      const id = ++nextId;
      timers.set(id, { callback, at: now + delayMs });
      return id;
    },
    clearTimeout(id) {
      timers.delete(id);
    },
    advance(milliseconds) {
      now += milliseconds;
      for (const [id, timer] of timers) {
        if (timer.at <= now) {
          timers.delete(id);
          timer.callback();
        }
      }
    },
  };
}



const observations=[];
for(const placement of ['leading','trailing','between']){
 let notify,finished=false;
 const work1=timeline([['tool-1']])[0],work2=timeline([['tool-2']])[0];
 const thought=()=>({id:fullId('op:reasoning:pending'),kind:'system',operationKind:'reasoning',status:finished?'completed':'pending',startedAt:1000,completedAt:finished?5000:null});
 const ids=placement==='leading'?['op:reasoning:pending','tool-1']:placement==='trailing'?['tool-1','op:reasoning:pending']:['tool-1','op:reasoning:pending','tool-2'];
 const dom=mountDom({rowIds:ids,fetchTimeline:async()=>placement==='leading'?[thought(),work1]:placement==='trailing'?[work1,thought()]:[work1,thought(),work2],subscribeTimeline:cb=>{notify=cb;return()=>{}}});
 try{
  await dom.flush();const thoughtRow=dom.rows[ids.indexOf('op:reasoning:pending')];
  const sample=()=>({activity:dom.container.querySelector('[data-bb-minus-group]')?.getAttribute('data-tool-state'),metrics:dom.container.querySelector('[data-metrics]')?.textContent,groups:dom.container.querySelectorAll('[data-metrics]').length});
  const before=sample();thoughtRow.remove();await dom.flush();const unmounted=sample();
  assert.equal(unmounted.activity,'pending');assert.equal(unmounted.metrics,placement==='between'?'2 tools':'1 tool');assert.equal(unmounted.groups,1);
  const metrics=dom.container.querySelector('[data-metrics]');metrics.focus();metrics.click();await dom.flush();
  dom.container.insertBefore(thoughtRow,placement==='trailing'?null:dom.rows[placement==='leading'?1:2]);await dom.flush();const returned=sample();
  assert.equal(returned.activity,'pending');assert.equal(dom.window.document.activeElement,metrics);
  thoughtRow.remove();await dom.flush();finished=true;notify('thr_test',true);await dom.flush();const after=sample();
  assert.equal(after.activity,'completed');assert.equal(after.metrics,placement==='between'?'2 tools · 600ms':'1 tool · 300ms');
  observations.push({placement,before,unmounted,returned,after,passed:true});
 }finally{dom.cleanup()}
}
console.log(JSON.stringify(observations));

